 "content": "def transform(grid):
    """Overlay the two nonzero masks separated by a solid divider; mark overlap with 2."""
    h, w = len(grid), len(grid[0])
    # Find a full-width or full-height solid divider between equal-sized panels.
    for r, row in enumerate(grid):
        if r > 0 and r < h - 1 and len(set(row)) == 1 and row[0] != 0:
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                        for ra, rb in zip(top, bottom)]
    for c in range(w):
        if c > 0 and c < w - 1 and all(row[c] == grid[0][c] and row[c] != 0 for row in grid):
            left_w, right_w = c, w - c - 1
            if left_w == right_w:
                return [[2 if row[j] != 0 and row[c + 1 + j] != 0 else 0
                         for j in range(left_w)] for row in grid]
    raise ValueError("No centered solid divider separating equal-sized panels")
